const ticket = $input.item.json.body ?? {};

const errors = [];

const ticketId = ticket.ticketId;
const customerEmail = ticket.customerEmail;
const message = ticket.message;

// Validate ticket ID
if (
  typeof ticketId !== "string" ||
  ticketId.trim() === ""
) {
  errors.push("Invalid ticket ID");
}

// Validate customer email
if (
  typeof customerEmail !== "string" ||
  !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(customerEmail)
) {
  errors.push("Invalid customer email");
}

// Validate ticket message
if (
  typeof message !== "string" ||
  message.trim() === ""
) {
  errors.push("Invalid ticket message");
}

return {
  json: {
    ticketId: typeof ticketId === "string"
      ? ticketId.trim()
      : null,
    customerEmail: typeof customerEmail === "string"
      ? customerEmail.trim()
      : null,
    message: typeof message === "string"
      ? message.trim()
      : null,
    isValid: errors.length === 0,
    errors,
    status: errors.length === 0
      ? "VALIDATED"
      : "VALIDATION_ERROR"
  }
};

const ticket = $('Validate Ticket').item.json;
const ai = $input.item.json;
const allowedCategories = ['SHIPPING', 'REFUND', 'BILLING', 'GENERAL'];
function output(classification, httpStatus, processingStatus) {
  return { json: { ...ticket, classification, httpStatus, processingStatus } };
}
// Ollama continues failures as an error item. Do not return raw error details.
if (Object.prototype.hasOwnProperty.call(ai, 'error')) {
  return output({ category: 'UNKNOWN', reason: '', isValid: false,
    requiresReview: true, errorCode: 'AI_UNAVAILABLE' }, 503, 'AI_UNAVAILABLE');
}
try {
  const parsed = typeof ai.content === 'string' ? JSON.parse(ai.content) : ai.content;
  const valid = parsed !== null && typeof parsed === 'object' && !Array.isArray(parsed)
    && allowedCategories.includes(parsed.category)
    && typeof parsed.reason === 'string'
    && parsed.reason.trim().length > 0 && parsed.reason.trim().length <= 500;
  if (valid) {
    return output({ category: parsed.category, reason: parsed.reason.trim(),
      isValid: true, requiresReview: false }, 200, 'CLASSIFIED');
  }
} catch {
  // Discard untrusted model output and parser details.
}
return output({ category: 'UNKNOWN', reason: '', isValid: false,
  requiresReview: true, errorCode: 'INVALID_AI_OUTPUT' }, 200, 'CLASSIFICATION_REVIEW_REQUIRED');

const ticket = $input.item.json;

// Only already-validated tickets may enter the future persistence path.
if (ticket.isValid !== true) {
  throw new Error('Prepare Ticket Claim requires a valid ticket');
}

for (const field of ['ticketId', 'customerEmail', 'message']) {
  if (typeof ticket[field] !== 'string' || ticket[field].trim().length === 0) {
    throw new Error('Prepare Ticket Claim requires nonempty ticket fields');
  }
}

// MySQL VARCHAR limits count characters, including one character per emoji.
if (Array.from(ticket.ticketId).length > 128) {
  throw new Error('ticketId exceeds the 128-character database limit');
}
if (Array.from(ticket.customerEmail).length > 254) {
  throw new Error('customerEmail exceeds the 254-character database limit');
}

// MySQL TEXT is limited to 65,535 bytes; Unicode characters may use multiple bytes.
if (Buffer.byteLength(ticket.message, 'utf8') > 65535) {
  throw new Error('message exceeds the 65535-byte database limit');
}

// Fingerprint contract: JSON array in this exact order, using the values already
// normalized by Validate Ticket. Preserve case and content; do not trim again.
// Exclude policy version, execution ID and timestamps so retries remain stable.
const fingerprintInput = JSON.stringify([
  ticket.ticketId,
  ticket.customerEmail,
  ticket.message,
]);

return {
  json: {
    ...ticket,
    fingerprintInput,
    policyVersion: 'v1',
  },
};

const input = $input.item;
let ticket;
try { ticket = $('Fingerprint Ticket').item.json; }
catch { return { json: { claimOutcome: 'FAILURE', httpStatus: 503, errorCode: 'TICKET_CLAIM_FAILED' } }; }
const prepared = {
  ticketId: ticket.ticketId, customerEmail: ticket.customerEmail, message: ticket.message,
  isValid: ticket.isValid, errors: ticket.errors, status: ticket.status,
  payloadFingerprint: ticket.payloadFingerprint, policyVersion: ticket.policyVersion,
};
const row = input.json;
if (input.error === undefined && !Object.prototype.hasOwnProperty.call(row, 'error')
    && row.ticket_id === ticket.ticketId && typeof row.payload_fingerprint === 'string') {
  if (row.claim_outcome === 'NEW' && row.execution_id === String($execution.id)
      && row.payload_fingerprint === ticket.payloadFingerprint
      && row.processing_status === 'PROCESSING' && Number(row.claim_audit_rows) === 1) {
    return { json: { ...prepared, claimOutcome: 'NEW' } };
  }
  if (row.claim_outcome === 'DUPLICATE' && row.execution_id !== String($execution.id)
      && Number(row.claim_audit_rows) === 0) {
    return { json: { ...prepared, claimOutcome: 'DUPLICATE' } };
  }
}
// A 1062 error (including audit collisions) is a failure, never proof of a duplicate.
return { json: { ...prepared, claimOutcome: 'FAILURE', httpStatus: 503, errorCode: 'TICKET_CLAIM_FAILED' } };

const incoming = $('Fingerprint Ticket').item.json;
const row = $input.item.json;
if (row.ticket_id !== incoming.ticketId || typeof row.payload_fingerprint !== 'string') {
  return { json: { httpStatus: 503, errorCode: 'TICKET_LOOKUP_FAILED', ...incoming } };
}
if (row.payload_fingerprint !== incoming.payloadFingerprint) {
  return { json: { ticketId: incoming.ticketId, customerEmail: incoming.customerEmail,
    message: incoming.message, httpStatus: 409, errorCode: 'TICKET_ID_CONFLICT' } };
}
return { json: { resultKind: 'REPLAY', row } };

const ticket = $('Fingerprint Ticket').item.json;
const result = $input.item.json;
const classification = result.classification || {};
const categories = ['SHIPPING', 'REFUND', 'BILLING', 'GENERAL'];
const valid = classification.isValid === true && categories.includes(classification.category)
  && typeof classification.reason === 'string' && classification.reason.trim().length > 0
  && classification.reason.length <= 500;
const unavailable = classification.errorCode === 'AI_UNAVAILABLE' || result.httpStatus === 503;
const processingStatus = unavailable ? 'FAILED' : valid ? 'AUTO_ROUTED' : 'PENDING_REVIEW';
return { json: {
  ticketId: ticket.ticketId, customerEmail: ticket.customerEmail, message: ticket.message,
  payloadFingerprint: ticket.payloadFingerprint, policyVersion: ticket.policyVersion,
  executionId: String($execution.id),
  category: valid && !unavailable ? classification.category : 'UNKNOWN',
  reason: valid && !unavailable ? classification.reason.trim() : '',
  requiresReview: !valid && !unavailable ? '1' : '0',
  reviewReason: unavailable ? 'AI_UNAVAILABLE' : valid ? '' : 'INVALID_AI_OUTPUT',
  processingStatus,
  auditEvent: unavailable ? 'MODEL_UNAVAILABLE' : valid ? 'AI_CLASSIFICATION_ACCEPTED' : 'HUMAN_REVIEW_REQUESTED',
  eventKey: 'FINAL_OUTCOME:' + ticket.policyVersion,
} };

let ticket = {};
try { ticket = $('Validate Ticket').item.json; } catch {}
const input = $input.item;
const rawMessage = input.error?.message || input.json.error?.message || input.json.error || input.json.message;
// Code-node errors append a line number. Strip only that suffix before allowlisting.
const message = typeof rawMessage === 'string' ? rawMessage.replace(/ \[line \d+\]$/, '') : '';
const lengthErrors = [
  'ticketId exceeds the 128-character database limit',
  'customerEmail exceeds the 254-character database limit',
  'message exceeds the 65535-byte database limit',
];
const invalidLength = lengthErrors.includes(message);
return { json: {
  ticketId: ticket.ticketId, customerEmail: ticket.customerEmail, message: ticket.message,
  httpStatus: invalidLength ? 400 : 503,
  errorCode: invalidLength ? 'TICKET_FIELD_TOO_LONG' : 'TICKET_PROCESSING_UNAVAILABLE',
  validationErrors: invalidLength ? [message] : [],
} };

const data = $input.item.json;
function failure(code = 'TICKET_PROCESSING_UNAVAILABLE') {
  let ticket = {};
  try { ticket = $('Validate Ticket').item.json; } catch {}
  return { json: { ticketId: ticket.ticketId, customerEmail: ticket.customerEmail,
    message: ticket.message, status: 'SERVICE_UNAVAILABLE', errorCode: code, httpStatus: 503 } };
}
try {
  if ([400, 409, 503].includes(data.httpStatus)) {
    const allowed = ['TICKET_FIELD_TOO_LONG', 'TICKET_ID_CONFLICT', 'TICKET_LOOKUP_FAILED',
      'TICKET_CLAIM_FAILED', 'CLAIM_CONTEXT_UNAVAILABLE', 'TICKET_PROCESSING_UNAVAILABLE'];
    const code = allowed.includes(data.errorCode) ? data.errorCode : 'TICKET_PROCESSING_UNAVAILABLE';
    return { json: { ticketId: data.ticketId, customerEmail: data.customerEmail,
      message: data.message, status: data.httpStatus === 409 ? 'CONFLICT'
        : data.httpStatus === 400 ? 'VALIDATION_ERROR' : 'SERVICE_UNAVAILABLE',
      errorCode: code, ...(data.httpStatus === 400 ? { isValid: false, errors: data.validationErrors || [] } : {}),
      httpStatus: data.httpStatus } };
  }
  const replay = data.resultKind === 'REPLAY';
  const row = replay ? data.row : data;
  if (!replay && (Number(row.updated_rows) !== 1 || Number(row.audit_rows) !== 1)) return failure('TICKET_PROCESSING_UNAVAILABLE');
  if (!row || typeof row.ticket_id !== 'string') return failure();
  const fields = { ticketId: row.ticket_id, customerEmail: row.customer_email, message: row.customer_message };
  if (row.processing_status === 'PROCESSING') {
    return { json: { ...fields, status: 'PROCESSING', processingStatus: 'PROCESSING', httpStatus: 202 } };
  }
  if (row.processing_status === 'FAILED') {
    return { json: { ...fields, status: 'SERVICE_UNAVAILABLE', errorCode: 'AI_UNAVAILABLE', httpStatus: 503 } };
  }
  if (row.processing_status === 'PENDING_REVIEW') {
    return { json: { ...fields, isValid: true, errors: [], status: 'PENDING_REVIEW',
      classification: { category: 'UNKNOWN', reason: '', isValid: false, requiresReview: true, errorCode: 'INVALID_AI_OUTPUT' },
      processingStatus: 'PENDING_REVIEW', httpStatus: 202 } };
  }
  if (row.processing_status !== 'AUTO_ROUTED' || !['SHIPPING','REFUND','BILLING','GENERAL'].includes(row.classification_category)
      || typeof row.classification_reason !== 'string' || !row.classification_reason.trim()) return failure();
  return { json: { ...fields, isValid: true, errors: [], status: 'VALIDATED',
    classification: { category: row.classification_category, reason: row.classification_reason,
      isValid: true, requiresReview: false }, httpStatus: 200, processingStatus: 'CLASSIFIED' } };
} catch { return failure(); }
